/* ubg: GameDistribution ad SDK removed - no-op stub. Ads "complete" at once so nothing waits on them; no network, no domain check. */
(function () {
  var w = window;
  function ev(name) {
    try { var o = w.GD_OPTIONS; if (o && typeof o.onEvent === 'function') o.onEvent({ name: name }); } catch (e) {}
  }
  function done(type) {
    ev('SDK_GAME_PAUSE');
    return new Promise(function (res) {
      setTimeout(function () {
        if (type === 'rewarded') ev('SDK_REWARDED_WATCH_COMPLETE');
        ev('SDK_GAME_START');
        res({});
      }, 30);
    });
  }
  var base = {
    showAd: function (t) { return done(t); },
    preloadAd: function () { return Promise.resolve({}); },
    cancelAd: function () { return Promise.resolve({}); },
    showBanner: function () { return Promise.resolve({}); },
    openConsole: function () {},
    showLeaderBoard: function () { return Promise.resolve({}); },
    executeStoreAction: function () { return Promise.resolve({}); },
    store: { isVisible: false }
  };
  w.gdsdk = new Proxy(base, { get: function (t, k) { return k in t ? t[k] : function () { return Promise.resolve({}); }; } });
  w.GD_OPTIONS = w.GD_OPTIONS || {};
  setTimeout(function () { ev('SDK_READY'); ev('SDK_GAME_START'); }, 300);
})();
